class Solution:
    def max_profit(self, prices: list[int]) -> int:
        """Find the maximum profit generated by buying and selling stock.

        Args:
            prices (list[int]): integer array representing daily stock prices

        Returns:
            int: maximum profit generated by buying and selling stock

        Time complexity: O(n) - len(prices)

        Space complexity: O(1)
        """

        # prices = [10,20,60,20]

        max_profit = 0
        buy = 0
        sell = 1

        while sell < len(prices):

            if prices[sell] <= prices[buy]:
                buy = sell

            else:
                curr_profit = prices[sell] - prices[buy]
                max_profit = max(max_profit, curr_profit)

            sell += 1

        return max_profit

s = Solution()

def check(values, expected):
    result = s.max_profit(values)
    assert result == expected

check([10,10,10,10], 0)
check([30,20,10,5], 0)
check([10,20,30,40], 30)
check([10,20], 10)
check([20,10], 0)
check([], 0)
check([2], 0)
check([9,3,2,7,10], 8)
print("all tests passed")

